INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(264519, 18029, 327, '<td valign="top">Nice compostion. Nice color. Not too sure about the ?filter used?</td>', 'Nice compostion. Nice color. Not too sure about the ?filter used?', '2003-04-14 01:14:35.000000', NULL, 1),
(264520, 18214, 327, '<td valign="top">I tried shooting these....kept melting, what a mess I made. I had them in the freezer but still my lights are hot. You did well~</td>', 'I tried shooting these....kept melting, what a mess I made. I had them in the freezer but still my lights are hot. You did well~', '2003-04-14 01:15:43.000000', NULL, 1),
(264521, 18084, 3669, '<td valign="top">The sparkle off the glass is a really cool effect.  However, the glare on the glass and the darkness of the candy subject is a bit distracting.  Maybe could have cropped a little closer.  I''m scoring for the sparkle only.</td>', 'The sparkle off the glass is a really cool effect.  However, the glare on the glass and the darkness of the candy subject is a bit distracting.  Maybe could have cropped a little closer.  I''m scoring for the sparkle only.', '2003-04-14 01:16:19.000000', NULL, 1),
(264531, 18029, 4267, '<td valign="top">wow you took a tremendous amount of time setting that up.. exposure level is great, but it needs sharper focus... something about it, maybe the processing that makes it look almost painted rather than a photograph... sharp focus and less processing would have made this a 10</td>', 'wow you took a tremendous amount of time setting that up.. exposure level is great, but it needs sharper focus... something about it, maybe the processing that makes it look almost painted rather than a photograph... sharp focus and less processing would have made this a 10', '2003-04-14 01:17:22.000000', NULL, 1),
(264533, 18096, 3669, '<td valign="top">Just a tad too washed out for my taste...otherwise a nicely done photo.</td>', 'Just a tad too washed out for my taste...otherwise a nicely done photo.', '2003-04-14 01:17:45.000000', NULL, 1),
(264537, 18062, 327, '<td valign="top">Pretty colors, lighting. Love the composition. Good job.</td>', 'Pretty colors, lighting. Love the composition. Good job.', '2003-04-14 01:19:00.000000', NULL, 1),
(264539, 18098, 327, '<td valign="top">Looks good. YUM</td>', 'Looks good. YUM', '2003-04-14 01:19:34.000000', NULL, 1),
(264544, 18125, 3669, '<td valign="top">A little dark.  I''m thinking that the "coins" should be a little more shiny.  The chocolate doesn''t really seem all that appealing...however, having worked with candy all week, nothing seems very appealing anymore.  In any event, it''s otherwise a nice picture.  It''s nicely focused and well composed....just too dark.</td>', 'A little dark.  I''m thinking that the "coins" should be a little more shiny.  The chocolate doesn''t really seem all that appealing...however, having worked with candy all week, nothing seems very appealing anymore.  In any event, it''s otherwise a nice picture.  It''s nicely focused and well composed....just too dark.', '2003-04-14 01:21:06.000000', NULL, 1),
(264545, 18211, 5391, '<td valign="top">Funny and clever!  From looking at the thumbnails, this seems to be the most original of the bunch.  8</td>', 'Funny and clever!  From looking at the thumbnails, this seems to be the most original of the bunch.  8', '2003-04-14 01:21:53.000000', NULL, 1),
(264552, 18029, 3669, '<td valign="top">Sea of M&amp;M''s.  This set-up had to take a long time.  The ultra sharp focus made for an interesting effect, however, it gave it more of a computer graphic feel than photography, if you get my point.</td>', 'Sea of M&M''s.  This set-up had to take a long time.  The ultra sharp focus made for an interesting effect, however, it gave it more of a computer graphic feel than photography, if you get my point.', '2003-04-14 01:24:52.000000', NULL, 1),
(264553, 17951, 7504, '<td valign="top">I love this one!  Great models and cool spaghetti licorice!</td>', 'I love this one!  Great models and cool spaghetti licorice!', '2003-04-14 01:25:16.000000', NULL, 1),
(264566, 17616, 3669, '<td valign="top">Ugg!  I hope you didn''t actually EAT all that!!  Good idea, but the lack of focus causes as much nausea as eating the lot.</td>', 'Ugg!  I hope you didn''t actually EAT all that!!  Good idea, but the lack of focus causes as much nausea as eating the lot.', '2003-04-14 01:27:38.000000', NULL, 1),
(264571, 18217, 3669, '<td valign="top">I think that this would have been a better photo if the wrapper had been taken off.  It caused a lot of glare.</td>', 'I think that this would have been a better photo if the wrapper had been taken off.  It caused a lot of glare.', '2003-04-14 01:28:47.000000', NULL, 1),
(264583, 18192, 3669, '<td valign="top">Nice still action shot, but the falling candies are in the dark and the pile of Skittles are blurry and have a lot of glare.  Very good idea, but it just didn''t appeal to me as it should.</td>', 'Nice still action shot, but the falling candies are in the dark and the pile of Skittles are blurry and have a lot of glare.  Very good idea, but it just didn''t appeal to me as it should.', '2003-04-14 01:32:13.000000', NULL, 1),
(264589, 17706, 3669, '<td valign="top">Very good idea.  Nicely performed.</td>', 'Very good idea.  Nicely performed.', '2003-04-14 01:33:53.000000', NULL, 1),
(264602, 18153, 1344, '<td valign="top">Mmmmm beer...  Mmmmm T&amp;A...  Mmmmm 3.</td>', 'Mmmmm beer...  Mmmmm T&A...  Mmmmm 3.', '2003-04-14 01:37:34.000000', NULL, 1),
(264605, 18115, 3669, '<td valign="top">A good idea and nicely set-up.  For some reason, the color of the glass on the right bothers me.  It has a green hue to it and my eyes went right to it.  Other than the wrinkle in the background on the top left, it''s my only complaint.  Otherwise, good composition, well focused and a nice take on the challenge.</td>', 'A good idea and nicely set-up.  For some reason, the color of the glass on the right bothers me.  It has a green hue to it and my eyes went right to it.  Other than the wrinkle in the background on the top left, it''s my only complaint.  Otherwise, good composition, well focused and a nice take on the challenge.', '2003-04-14 01:38:03.000000', NULL, 1),
(264609, 18029, 1344, '<td valign="top">Jeez, that musta taken a while....  Colors look weird..   Very noisy too.</td>', 'Jeez, that musta taken a while....  Colors look weird..   Very noisy too.', '2003-04-14 01:39:12.000000', NULL, 1),
(264612, 17706, 1344, '<td valign="top">I was gonna get my wife to put on silver lipstick (she didnt have any) and have the "Kisses" tag hanging out of her lips.  Thought that''d be a cool shot..</td>', 'I was gonna get my wife to put on silver lipstick (she didnt have any) and have the "Kisses" tag hanging out of her lips.  Thought that''d be a cool shot..', '2003-04-14 01:41:14.000000', NULL, 1),
(264616, 18258, 3669, '<td valign="top">LOL...I like it.  Appears to be a Cadbury Ad.  They should compensate you.  Peeps are cute but nauseaous.  Anyway, I like the compostion of this picture.  The colors came out nicely...might be a tad out of focus.</td>', 'LOL...I like it.  Appears to be a Cadbury Ad.  They should compensate you.  Peeps are cute but nauseaous.  Anyway, I like the compostion of this picture.  The colors came out nicely...might be a tad out of focus.', '2003-04-14 01:41:53.000000', NULL, 1),
(264621, 18046, 1344, '<td valign="top">Went a little crazy with the borders dude.. Somewhat interesting photo tho.</td>', 'Went a little crazy with the borders dude.. Somewhat interesting photo tho.', '2003-04-14 01:42:56.000000', NULL, 1),
(264622, 18270, 7504, '<td valign="top">I love it''s simplicity.  Very nice.</td>', 'I love it''s simplicity.  Very nice.', '2003-04-14 01:43:07.000000', NULL, 1),
(264630, 18129, 4715, '<td valign="top">excellent! how''d you focus on two spots?</td>', 'excellent! how''d you focus on two spots?', '2003-04-14 01:44:39.000000', NULL, 1),
(264631, 18264, 7504, '<td valign="top">Very fun concept.</td>', 'Very fun concept.', '2003-04-14 01:44:57.000000', NULL, 1),
(264633, 18231, 7504, '<td valign="top">Whoa!  That''s what I call a macro!  Good job!</td>', 'Whoa!  That''s what I call a macro!  Good job!', '2003-04-14 01:45:27.000000', NULL, 1),
(264635, 18214, 4715, '<td valign="top">mm too much yellow for my taste</td>', 'mm too much yellow for my taste', '2003-04-14 01:45:51.000000', NULL, 1),
(264636, 18153, 7838, '<td valign="top">hmm.. my weaknesses.. women and alcohol.  good shot - definitely out of the box...  maybe you could have moved a little closer to the 6-oclock position to get rid of the feet  next to the brunette''s head at upper left corner.....</td>', 'hmm.. my weaknesses.. women and alcohol.  good shot - definitely out of the box...  maybe you could have moved a little closer to the 6-oclock position to get rid of the feet  next to the brunette''s head at upper left corner.....', '2003-04-14 01:46:23.000000', NULL, 1),
(264639, 18129, 7504, '<td valign="top">Can''t figure this out how you did this, very cool!</td>', 'Can''t figure this out how you did this, very cool!', '2003-04-14 01:46:58.000000', NULL, 1),
(264645, 18211, 7504, '<td valign="top">Oh this is very cute.  I got a good giggle out of this!</td>', 'Oh this is very cute.  I got a good giggle out of this!', '2003-04-14 01:48:40.000000', NULL, 1),
(264647, 18165, 7838, '<td valign="top">i think maybe the lightingof this picture should have been about 5 oclock to lighten up the edges for detail.  nice shot otherwise.  doesn''t look like any chocolate i am used to seeing.  what is it?</td>', 'i think maybe the lightingof this picture should have been about 5 oclock to lighten up the edges for detail.  nice shot otherwise.  doesn''t look like any chocolate i am used to seeing.  what is it?', '2003-04-14 01:48:58.000000', NULL, 1),
(264648, 18178, 7838, '<td valign="top">makes a mouth happy..........</td>', 'makes a mouth happy..........', '2003-04-14 01:49:26.000000', NULL, 1),
(264655, 18214, 7838, '<td valign="top">i like all the different angles. awesome idea -- i wont touch it. nice effect with the dripping gel.  i don''t care for the different shad of red in the background, tho</td>', 'i like all the different angles. awesome idea -- i wont touch it. nice effect with the dripping gel.  i don''t care for the different shad of red in the background, tho', '2003-04-14 01:52:12.000000', NULL, 1),
(264659, 18105, 7504, '<td valign="top">Very nice.  I like the simplicity of it and that you were brave enough to use white on a candy challenge!</td>', 'Very nice.  I like the simplicity of it and that you were brave enough to use white on a candy challenge!', '2003-04-14 01:52:32.000000', NULL, 1),
(264661, 18085, 7504, '<td valign="top">Is that lettuce?  It''s hard to tell, as it''s a bit over exposed.  Great idea though!</td>', 'Is that lettuce?  It''s hard to tell, as it''s a bit over exposed.  Great idea though!', '2003-04-14 01:53:36.000000', NULL, 1),
(264663, 18013, 7838, '<td valign="top">nice idea.  i think the candy should have been focused on and should be brighter,  because the sun takes precedence over the picture.  i like the sunspot in the glass. too bad the cloud wasn''t a little more centered.</td>', 'nice idea.  i think the candy should have been focused on and should be brighter,  because the sun takes precedence over the picture.  i like the sunspot in the glass. too bad the cloud wasn''t a little more centered.', '2003-04-14 01:54:17.000000', NULL, 1),
(264666, 18258, 7504, '<td valign="top">This is fun.  lol!</td>', 'This is fun.  lol!', '2003-04-14 01:57:54.000000', NULL, 1),
(264667, 18123, 7504, '<td valign="top">Wow, this is very clean and sharp.  Nice job!  Oh, and I found that little rascal.</td>', 'Wow, this is very clean and sharp.  Nice job!  Oh, and I found that little rascal.', '2003-04-14 01:58:30.000000', NULL, 1),
