(264670, 18273, 6202, '<td valign="top">very cute,  looks like you have wiggly toes there.</td>', 'very cute,  looks like you have wiggly toes there.', '2003-04-14 02:00:01.000000', NULL, 1),
(264671, 18251, 7504, '<td valign="top">LOL!  This is very funny!  Great idea and good execution.</td>', 'LOL!  This is very funny!  Great idea and good execution.', '2003-04-14 02:00:13.000000', NULL, 1),
(264672, 18278, 7504, '<td valign="top">Nice pun.</td>', 'Nice pun.', '2003-04-14 02:00:43.000000', NULL, 1),
