(264679, 18062, 7504, '<td valign="top">Very colorful and yummy looking.  I like your choice of colors for this.</td>', 'Very colorful and yummy looking.  I like your choice of colors for this.', '2003-04-14 02:04:25.000000', NULL, 1),
(264684, 18234, 3669, '<td valign="top">I swear this picture looks like a one taken under a microscope of some weird bacteria.  Good detail shown of single sugar grains.  Turns out to be a nice abstract photo.</td>', 'I swear this picture looks like a one taken under a microscope of some weird bacteria.  Good detail shown of single sugar grains.  Turns out to be a nice abstract photo.', '2003-04-14 02:10:25.000000', NULL, 1),
(264685, 18031, 3669, '<td valign="top">Appears a bit flat.  Could use some adjustments to contrast to bring out the colors more.  Otherwise, would be a very nice candy photo.</td>', 'Appears a bit flat.  Could use some adjustments to contrast to bring out the colors more.  Otherwise, would be a very nice candy photo.', '2003-04-14 02:12:02.000000', NULL, 1),
(264687, 17842, 3669, '<td valign="top">Very nice shot.  You were able to pick up the texture of the sugar.  The lighting is great.  What more can I say?  WOW!  This should make at least the top 3 if not 1st.  Good luck this week.</td>', 'Very nice shot.  You were able to pick up the texture of the sugar.  The lighting is great.  What more can I say?  WOW!  This should make at least the top 3 if not 1st.  Good luck this week.', '2003-04-14 02:16:42.000000', NULL, 1),
(264689, 18105, 3669, '<td valign="top">Very nice idea using white on white.  Very cool and refreashing.</td>', 'Very nice idea using white on white.  Very cool and refreashing.', '2003-04-14 02:18:03.000000', NULL, 1),
(264690, 17951, 3669, '<td valign="top">Very nice idea using the Disney theme.  Well done.</td>', 'Very nice idea using the Disney theme.  Well done.', '2003-04-14 02:19:25.000000', NULL, 1),
