(264694, 18084, 6900, '<td valign="top">I like the star reflection, but not the one higher up.  It''s all a bit dark, but I like the subject and way you chose to do this.</td>', 'I like the star reflection, but not the one higher up.  It''s all a bit dark, but I like the subject and way you chose to do this.', '2003-04-14 02:20:52.000000', NULL, 1),
(264695, 18232, 3669, '<td valign="top">I would have liked to see this cropped closer to remove the pipes or whatever they are and the store background....then all you can see are the gumball machines.  Otherwise a very nice photo</td>', 'I would have liked to see this cropped closer to remove the pipes or whatever they are and the store background....then all you can see are the gumball machines.  Otherwise a very nice photo', '2003-04-14 02:21:30.000000', NULL, 1),
(264696, 18119, 6900, '<td valign="top">The background detracts a little from the subject and I wish there were TWO green leaves! :)  I was having trouble figuring out why there was one at first.</td>', 'The background detracts a little from the subject and I wish there were TWO green leaves! :)  I was having trouble figuring out why there was one at first.', '2003-04-14 02:22:08.000000', NULL, 1),
(264698, 17916, 6900, '<td valign="top">Sweeeets! Yum.  :) What a great week for voting.  Thanks for making me hungry.</td>', 'Sweeeets! Yum.  :) What a great week for voting.  Thanks for making me hungry.', '2003-04-14 02:22:41.000000', NULL, 1),
