(264700, 18272, 6900, '<td valign="top">Classic done well.  Great lighting, but it looks a bit uneven?</td>', 'Classic done well.  Great lighting, but it looks a bit uneven?', '2003-04-14 02:23:37.000000', NULL, 1),
(264701, 18046, 3669, '<td valign="top">I would have voted higher for this photo had it not been for the bulky frame around it.  Too much for such a simple picture.  I like the snow and how the color in some of the jelly beans have bled into it.</td>', 'I would have voted higher for this photo had it not been for the bulky frame around it.  Too much for such a simple picture.  I like the snow and how the color in some of the jelly beans have bled into it.', '2003-04-14 02:24:26.000000', NULL, 1),
