(265060, 17951, 7639, '<td valign="top">Great licorice ad.  Got licorice?  I could also see this cropped to the faces.</td>', 'Great licorice ad.  Got licorice?  I could also see this cropped to the faces.', '2003-04-14 07:52:56.000000', NULL, 1),
(265061, 18231, 7639, '<td valign="top">Do these come in brown?  Yuk.</td>', 'Do these come in brown?  Yuk.', '2003-04-14 07:54:15.000000', NULL, 1),
(265062, 18129, 4482, '<td valign="top">How the H*** did you do this?!?!?!? Nice shot!</td>', 'How the H*** did you do this?!?!?!? Nice shot!', '2003-04-14 07:55:10.000000', NULL, 1),
(265064, 18164, 4482, '<td valign="top">Mmmmmm Milka!!! Brings back memories from Germany!!</td>', 'Mmmmmm Milka!!! Brings back memories from Germany!!', '2003-04-14 07:55:53.000000', NULL, 1),
(265066, 17951, 4482, '<td valign="top">Brilliant idea! Too bad the plate is off centered. It creates an unbalance in the photo. The desaturation really works here though! 7</td>', 'Brilliant idea! Too bad the plate is off centered. It creates an unbalance in the photo. The desaturation really works here though! 7', '2003-04-14 07:58:02.000000', NULL, 1),
(265067, 18029, 4482, '<td valign="top">WOW! Must have taken you forever to set up!!! :-)  And I hope you have friends to help you eat them all!!</td>', 'WOW! Must have taken you forever to set up!!! :-)  And I hope you have friends to help you eat them all!!', '2003-04-14 07:59:24.000000', NULL, 1),
(265071, 18046, 4482, '<td valign="top">Hmmmmm...  I can barely see the candy and they look out of focus. I think you''re trying to save it by adding this HUGE frame around it! It''s a really nice frame though but IMO doesn''t add to the photo. 3</td>', 'Hmmmmm...  I can barely see the candy and they look out of focus. I think you''re trying to save it by adding this HUGE frame around it! It''s a really nice frame though but IMO doesn''t add to the photo. 3', '2003-04-14 08:02:47.000000', NULL, 1),
(265074, 18153, 4482, '<td valign="top">Hehehehe.... good try!!  ;-)</td>', 'Hehehehe.... good try!!  ;-)', '2003-04-14 08:04:22.000000', NULL, 1),
(265081, 18214, 4482, '<td valign="top">Great idea! I think you might have placed in the top 3 with a crisp white bg to acccentuate the red cherry! The red bg really loses lots of impact here. 6</td>', 'Great idea! I think you might have placed in the top 3 with a crisp white bg to acccentuate the red cherry! The red bg really loses lots of impact here. 6', '2003-04-14 08:06:26.000000', NULL, 1),
(265083, 18123, 4482, '<td valign="top">Found it!!! the best M&amp;M shot here IMP! I''m not sure if the shallow DOF works here... but I have all week to think it through!  :-)7</td>', 'Found it!!! the best M&M shot here IMP! I''m not sure if the shallow DOF works here... but I have all week to think it through!  :-)7', '2003-04-14 08:08:43.000000', NULL, 1),
(265097, 18109, 2344, '<td valign="top">I''m not sure what you used for lighting but I''ll offer my suggestions.  I would have tried using a white reflector to pick up a little more shape of that bowl.  Would help emphasize its shape (which is like a trophy!) and make the candy look more like a prize.</td>', 'I''m not sure what you used for lighting but I''ll offer my suggestions.  I would have tried using a white reflector to pick up a little more shape of that bowl.  Would help emphasize its shape (which is like a trophy!) and make the candy look more like a prize.', '2003-04-14 08:16:31.000000', NULL, 1),
(265103, 18273, 2344, '<td valign="top">Aw the little cutie is having a quiet moment with his lollipop.  Your image looks overexposed which is a shame because you would have gotten slightly better colour saturation with a proper exposure..  I would have maybe cropped in a bit tighter too. Good luck!</td>', 'Aw the little cutie is having a quiet moment with his lollipop.  Your image looks overexposed which is a shame because you would have gotten slightly better colour saturation with a proper exposure..  I would have maybe cropped in a bit tighter too. Good luck!', '2003-04-14 08:18:00.000000', NULL, 1),
(265106, 18278, 2344, '<td valign="top">Took me a while to get it..... but in my defense it''s monday morning! Less depth of field would help to bring out the can "D" more against the other letters</td>', 'Took me a while to get it..... but in my defense it''s monday morning! Less depth of field would help to bring out the can "D" more against the other letters', '2003-04-14 08:19:31.000000', NULL, 1),
(265109, 17916, 2344, '<td valign="top">Why is it the prettiest candies are also the nastiest? (licorice! yuck!)  It''s got a very cool texture to it and you captured it nicely! The background is a bit dull, but a bit of extra light could improve it tremendously.  Good job!</td>', 'Why is it the prettiest candies are also the nastiest? (licorice! yuck!)  It''s got a very cool texture to it and you captured it nicely! The background is a bit dull, but a bit of extra light could improve it tremendously.  Good job!', '2003-04-14 08:21:40.000000', NULL, 1),
(265116, 18129, 2344, '<td valign="top">Very very cool idea.  My only gripe is that my eye doesn''t know where to look.  Should I look at the front left or the back right?  Still a very very cool idea</td>', 'Very very cool idea.  My only gripe is that my eye doesn''t know where to look.  Should I look at the front left or the back right?  Still a very very cool idea', '2003-04-14 08:23:37.000000', NULL, 1),
(265118, 18093, 2344, '<td valign="top">Ad gainum fifty poundums :P</td>', 'Ad gainum fifty poundums :P', '2003-04-14 08:24:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(265121, 18031, 2344, '<td valign="top">mmm pez and nerds (I think). The best kind of candy!</td>', 'mmm pez and nerds (I think). The best kind of candy!', '2003-04-14 08:25:37.000000', NULL, 1),
(265142, 18115, 5728, '<td valign="top">Nice set up, I particularly like the color combination you have chosen here. I gave it a 9 instead of a 10 because the creases in the background sheet at the back left and in the front are a little distracting.</td>', 'Nice set up, I particularly like the color combination you have chosen here. I gave it a 9 instead of a 10 because the creases in the background sheet at the back left and in the front are a little distracting.', '2003-04-14 08:45:19.000000', NULL, 1),
(265145, 18178, 5728, '<td valign="top">I like this photo a lot. The deeps tones of red are very saturated and look good here, and of course I love the humor aspect. Good crop, good job - 9.</td>', 'I like this photo a lot. The deeps tones of red are very saturated and look good here, and of course I love the humor aspect. Good crop, good job - 9.', '2003-04-14 08:46:54.000000', NULL, 1),
(265147, 18231, 5728, '<td valign="top">Excellent colors and choice composition. I can almost feel the softness of those sweets, choice - 9!</td>', 'Excellent colors and choice composition. I can almost feel the softness of those sweets, choice - 9!', '2003-04-14 08:47:48.000000', NULL, 1),
(265150, 17804, 5728, '<td valign="top">Awesome! Good choice of background color, it fits to the gummi bears perfectly. Good lighting set up as well, although the left side seems a tad darker than the right - 9.</td>', 'Awesome! Good choice of background color, it fits to the gummi bears perfectly. Good lighting set up as well, although the left side seems a tad darker than the right - 9.', '2003-04-14 08:49:28.000000', NULL, 1),
(265158, 18214, 5728, '<td valign="top">Very funny!! Focus and DOF is excellent, the chocolate is very sharp and the blobs give this image so much more charachter. The red background fits in very well and I almost gave it a ten except one thing bothers me a little. The edge of the table is a little distracting in the background, I would have prefered to see an unbroken background - 9. Gary.</td>', 'Very funny!! Focus and DOF is excellent, the chocolate is very sharp and the blobs give this image so much more charachter. The red background fits in very well and I almost gave it a ten except one thing bothers me a little. The edge of the table is a little distracting in the background, I would have prefered to see an unbroken background - 9. Gary.', '2003-04-14 08:52:20.000000', NULL, 1),
(265203, 18165, 92, '<td valign="top">I''ve never seen anything like this before. It looks yummy. What is it called ?</td>', 'I''ve never seen anything like this before. It looks yummy. What is it called ?', '2003-04-14 09:57:55.000000', NULL, 1),
