INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(267381, 18109, 4493, '<td valign="top">Good lighting, composition and colors. This is a pleasing shot. Well done.</td>', 'Good lighting, composition and colors. This is a pleasing shot. Well done.', '2003-04-15 13:00:40.000000', NULL, 1),
(267382, 18208, 2310, '<td valign="top">Nice composition!  I like the top left to bottom right movement that it creates.  I just wish it was more brightly lit or maybe more focused...</td>', 'Nice composition!  I like the top left to bottom right movement that it creates.  I just wish it was more brightly lit or maybe more focused...', '2003-04-15 13:00:48.000000', NULL, 1),
(267383, 18123, 4493, '<td valign="top">Them darned skittles! :-)<br/> <br/>Nice composition. I think the lighting might work better defused some. The highlights on the candies is a little bright. Otherwise, good colors and execution.</td>', 'Them darned skittles! :-) Nice composition. I think the lighting might work better defused some. The highlights on the candies is a little bright. Otherwise, good colors and execution.', '2003-04-15 13:01:46.000000', NULL, 1),
(267384, 18137, 2310, '<td valign="top">Nice composition!.  I think I would prefer not to see the reflection on the side of the tic tac container.</td>', 'Nice composition!.  I think I would prefer not to see the reflection on the side of the tic tac container.', '2003-04-15 13:01:49.000000', NULL, 1),
(267387, 18270, 4493, '<td valign="top">Stunning. I wish that the light was diffused more so the hotspot on the gumball was less, and I''d like to see the whole gumball shadow. I like the clean simple execution of this. Well done.</td>', 'Stunning. I wish that the light was diffused more so the hotspot on the gumball was less, and I''d like to see the whole gumball shadow. I like the clean simple execution of this. Well done.', '2003-04-15 13:03:30.000000', NULL, 1),
(267389, 17904, 4493, '<td valign="top">Now that is a lot of candy. Focus and white balance could be adjusted some to bring out the vibrant colors more. Another idea, would be a reshoot with just the containers in the background in the shot. Something more abstract in nature :-)</td>', 'Now that is a lot of candy. Focus and white balance could be adjusted some to bring out the vibrant colors more. Another idea, would be a reshoot with just the containers in the background in the shot. Something more abstract in nature :-)', '2003-04-15 13:05:06.000000', NULL, 1),
(267392, 18178, 4493, '<td valign="top">I like the high key of this shot. The lighting on the background if more even so as to be completely white would really make this photo jump off the page. I like your crop and composition.</td>', 'I like the high key of this shot. The lighting on the background if more even so as to be completely white would really make this photo jump off the page. I like your crop and composition.', '2003-04-15 13:06:12.000000', NULL, 1),
(267393, 18273, 2310, '<td valign="top">Very cute photograph...I would love to see the horizon line a little more...horizontal</td>', 'Very cute photograph...I would love to see the horizon line a little more...horizontal', '2003-04-15 13:06:50.000000', NULL, 1),
(267395, 18273, 4493, '<td valign="top">Nice. Simple and effective. Would a portrait mode, closer crop in on the kid have more impact? Also, a little boost in contrast would help bring out the texture in the wood. Still a very nice shot.</td>', 'Nice. Simple and effective. Would a portrait mode, closer crop in on the kid have more impact? Also, a little boost in contrast would help bring out the texture in the wood. Still a very nice shot.', '2003-04-15 13:08:47.000000', NULL, 1),
